@StateMachine.state_machine_kernel
     : forall (S : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF),
       Mixed.MixedMeasure MN MF ->
       forall FO : @Omega.SemanticOmega MF FI,
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       forall A : Type,
       @StateMachine.state_config S E MN A ->
       MF
         (PrimitiveStableHitting.stable_target (@StateMachine.state_config S E MN A)
            (UnifiedFrontier.stable_head E MN (S * A)))

@StateMachine.state_config_rel
     : forall (S : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF),
       @Measure.SemanticMeasureCoreLaws MF FI ->
       Mixed.MixedMeasure MN MF ->
       @Omega.SemanticOmega MF FI ->
       forall A B : Type,
       (A -> B -> Prop) ->
       @StateMachine.state_config S E MN A -> @StateMachine.state_config S E MN B -> Prop

@StateMachine.state_machine_complete_related
     : forall (S : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI) (MX : Mixed.MixedMeasure MN MF)
         (FO : @Omega.SemanticOmega MF FI) (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO),
       @Omega.SemanticOmegaLaws MF FI FO ->
       forall Select : @Omega.SemanticOmegaSelection MF FI FO,
       @RelationalClosure.relational_bind MF FI ->
       forall (A B : Type) (RR : A -> B -> Prop),
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (c : @StateMachine.state_config S E MN A) (d : @StateMachine.state_config S E MN B)
         (mu : MF (UnifiedFrontier.stable_head E MN (S * A)))
         (nu : MF (UnifiedFrontier.stable_head E MN (S * B))),
       @StateMachine.state_config_rel S E MN MF FI FC MX FO A B RR c d ->
       @PrimitiveStableHitting.stable_hitting MF FI FO (@StateMachine.state_config S E MN A)
         (UnifiedFrontier.stable_head E MN (S * A))
         (@StateMachine.state_machine_kernel S E MN MF FI MX FO Ord Select A) c mu ->
       @PrimitiveStableHitting.stable_hitting MF FI FO (@StateMachine.state_config S E MN B)
         (UnifiedFrontier.stable_head E MN (S * B))
         (@StateMachine.state_machine_kernel S E MN MF FI MX FO Ord Select B) d nu ->
       @Measure.sem_lift MF FI (UnifiedFrontier.stable_head E MN (S * A))
         (UnifiedFrontier.stable_head E MN (S * B))
         (@PEutt.ptree_stable_head_rel E MN (S * A) (S * B) (@State.state_result_rel S A B RR)
            (@StateMachine.state_bisim_candidate S E MN MF FI FC MX FO A B RR)) mu nu

@StateMachineScheduling.state_primitive_tree_approx
     : forall (St : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (A : Type) (n : nat) (c : @StateMachine.state_config St E MN A),
       @BindScheduling.equiv MF FI FO (UnifiedFrontier.stable_head E MN (St * A))
         (@StateMachineScheduling.state_primitive_approx St E MN MF FI MX FO A n c)
         (@PTreeKernel.ptree_hitting_approx E MN MF FI MX FO (St * A) n
            (@PTreeDefinition.observe E MN (St * A)
               (@State.run_state St E MN A
                  (@snd St (PTreeDefinition.ptree (Sum.sum1 (State.stateE St) E) MN A) c)
                  (@fst St (PTreeDefinition.ptree (Sum.sum1 (State.stateE St) E) MN A) c))))

@StateMachineScheduling.state_phase_grid_le_primitive
     : forall (St : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (A : Type) (n m : nat) (c : @StateMachine.state_config St E MN A),
       @Omega.sem_le MF FI FO (UnifiedFrontier.stable_head E MN (St * A))
         (@StateMachineScheduling.state_phase_grid St E MN MF FI MX FO A n m c)
         (@StateMachineScheduling.state_primitive_approx St E MN MF FI MX FO A
            ((n + 1) * (m + 1)) c)

@StateMachineScheduling.state_primitive_le_phase_split
     : forall (St : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (A : Type) (n m : nat),
       n <= m ->
       forall c : @StateMachine.state_config St E MN A,
       @Omega.sem_le MF FI FO (UnifiedFrontier.stable_head E MN (St * A))
         (@StateMachineScheduling.state_primitive_approx St E MN MF FI MX FO A n c)
         (@StateMachineScheduling.state_phase_split St E MN MF FI MX FO A n n m c)

@StateMachineScheduling.state_phase_grid_row_lub
     : forall (St : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI)
         (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO),
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       forall (Select : @Omega.SemanticOmegaSelection MF FI FO) (A : Type)
         (n : nat) (c : @StateMachine.state_config St E MN A),
       @Omega.sem_lub MF FI FO (UnifiedFrontier.stable_head E MN (St * A))
         (fun m : nat => @StateMachineScheduling.state_phase_grid St E MN MF FI MX FO A n m c)
         (@PrimitiveStableHitting.stable_hitting_approx MF FI FO
            (@StateMachine.state_config St E MN A) (UnifiedFrontier.stable_head E MN (St * A))
            (@StateMachine.state_machine_kernel St E MN MF FI MX FO Ord Select A) n c)

@StateMachineScheduling.state_machine_hitting_sound
     : forall (St : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI)
         (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO),
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       forall (Select : @Omega.SemanticOmegaSelection MF FI FO) (A : Type)
         (c : @StateMachine.state_config St E MN A)
         (out : MF (UnifiedFrontier.stable_head E MN (St * A))),
       @PrimitiveStableHitting.stable_hitting MF FI FO (@StateMachine.state_config St E MN A)
         (UnifiedFrontier.stable_head E MN (St * A))
         (@StateMachine.state_machine_kernel St E MN MF FI MX FO Ord Select A) c out ->
       @PTreeKernel.ptree_stable_hitting E MN MF FI MX FO (St * A)
         (@PTreeDefinition.observe E MN (St * A)
            (@State.run_state St E MN A
               (@snd St (PTreeDefinition.ptree (Sum.sum1 (State.stateE St) E) MN A) c)
               (@fst St (PTreeDefinition.ptree (Sum.sum1 (State.stateE St) E) MN A) c))) out

@StatePreservation.run_state_peutt
     : forall (S : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI) (MX : Mixed.MixedMeasure MN MF)
         (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       @RelationalClosure.relational_bind MF FI ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (A B : Type) (RR : A -> B -> Prop)
         (t : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A)
         (u : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN B)
         (s : S),
       @PEutt.peutt (Sum.sum1 (State.stateE S) E) MN MF FI FC MX FO A B RR t u ->
       @PEutt.peutt E MN MF FI FC MX FO (S * A) (S * B) (@State.state_result_rel S A B RR)
         (@State.run_state S E MN A t s) (@State.run_state S E MN B u s)

@StatePreservation.run_state_peutt_Proper
     : forall (S : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI) (MX : Mixed.MixedMeasure MN MF)
         (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       @RelationalClosure.relational_bind MF FI ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (A : Type) (s : S),
       @Morphisms.Proper
         (PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A ->
          PTreeDefinition.ptree E MN (S * A))
         (@Morphisms.respectful (PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A)
            (PTreeDefinition.ptree E MN (S * A))
            (@PEutt.peutt (Sum.sum1 (State.stateE S) E) MN MF FI FC MX FO A A (@eq A))
            (@PEutt.peutt E MN MF FI FC MX FO (S * A) (S * A)
               (@State.state_result_rel S A A (@eq A))))
         (fun t : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A =>
          @State.run_state S E MN A t s)

@StatePreservation.run_state_peutt_eq
     : forall (S : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI) (MX : Mixed.MixedMeasure MN MF)
         (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       @RelationalClosure.relational_bind MF FI ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (A : Type) (t u : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A) (s : S),
